import json, re
OUT = "/tmp/obench-cell-ae_f49uo/bench_opencode_regex-chess_uwlf8an7/re.json"
R = []
def add(p, r): R.append([p, r])

def name(i): return "abcdefgh"[i % 8] + str(8 - i // 8)
def inb(r, f): return 0 <= r < 8 and 0 <= f < 8

# ---- preprocessing ----
add(r"^(\S+) w (\S+) (\S+) \d+ \d+\s*$", r"S\1 \2 \3")
for d in range(8, 1, -1):
    add(str(d) + r"(?=[^ ]* )", "1" * d)
add("/", "")

# ---- move generation (source line starts with S) ----
def move(cons, newep="-", epreq=None, castreq=None):
    # cons: pos -> (class, newval or None)
    pat = "(?m)^S"; rep = r"\g<0>" + "\n" + "M"; g = 0; cur = 0
    for p in sorted(cons):
        cls, nv = cons[p]
        if p > cur:
            g += 1; pat += "(.{%d})" % (p - cur); rep += r"\g<%d>" % g
        g += 1; pat += "(%s)" % cls
        rep += (r"\g<%d>" % g) if nv is None else nv
        cur = p + 1
    if cur < 64:
        g += 1; pat += "(.{%d})" % (64 - cur); rep += r"\g<%d>" % g
    g += 1
    pat += " (%s) " % (castreq if castreq else r"\S+"); rep += " " + r"\g<%d>" % g + " "
    pat += (re.escape(epreq) if epreq else r"\S+") + "$"
    rep += newep
    add(pat, rep)

ORTH = [(-1,0),(1,0),(0,-1),(0,1)]
DIAG = [(-1,-1),(-1,1),(1,-1),(1,1)]
for s in range(64):
    r, f = divmod(s, 8)
    for dirs, cls in ((ORTH, "QR"), (DIAG, "QB")):
        for dr, df in dirs:
            for k in range(1, 8):
                rr, ff = r + k*dr, f + k*df
                if not inb(rr, ff): break
                c = {s: ("[%s]" % (cls + ("K" if k == 1 else "")), "1"),
                     rr*8+ff: ("[a-z1]", r"\g<PIECE>")}
                for j in range(1, k):
                    c[(r+j*dr)*8 + f+j*df] = ("1", None)
                # piece backref: need group number of from-square; handle below
                move.__dict__.setdefault("pending", []).append(c)
    for dr, df in [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]:
        rr, ff = r+dr, f+df
        if inb(rr, ff):
            move({s: ("N", "1"), rr*8+ff: ("[a-z1]", "N")})
    # pawns
    if 1 <= r <= 6:
        t = s - 8; pc = "Q" if r == 1 else "P"
        move({s: ("P", "1"), t: ("1", pc)})
        if r == 6:
            move({s: ("P", "1"), s-8: ("1", None), s-16: ("1", "P")}, newep=name(s-8))
        for df in (-1, 1):
            if inb(r-1, f+df):
                move({s: ("P", "1"), t+df: ("[a-z]", pc)})
        if r == 3:
            for df in (-1, 1):
                if inb(r, f+df):
                    move({s: ("P", "1"), s+df: ("p", "1"), s-8+df: ("1", "P")}, epreq=name(s-8+df))

# sliders: resolve piece backref by using the from-square group
def move_slider(c):
    s = [p for p in c if c[p][1] == "1" and c[p][0].startswith("[Q")][0]
    # compute group index of s
    g = 0; cur = 0; gs = None
    for p in sorted(c):
        if p > cur: g += 1
        g += 1
        if p == s: gs = g
        cur = p + 1
    c2 = {p: (cl, (r"\g<%d>" % gs) if nv == r"\g<PIECE>" else nv) for p, (cl, nv) in c.items()}
    move(c2)
for c in move.pending: move_slider(c)

# castling
move({60: ("K", "Y"), 61: ("1", "X"), 62: ("1", "K"), 63: ("R", "1")}, castreq=r"\S*K\S*")
move({60: ("K", "Y"), 59: ("1", "X"), 58: ("1", "K"), 57: ("1", None), 56: ("R", "1")}, castreq=r"\S*Q\S*")

add(r"(?m)^S.*$\n?", "")

# ---- check filter ----
def seq(cons):
    out = ""; cur = 0
    for p in sorted(cons):
        if p > cur: out += ".{%d}" % (p - cur)
        out += cons[p]; cur = p + 1
    return out
for s in range(64):
    r, f = divmod(s, 8)
    alts = []
    for dirs, cls in ((ORTH, "rq"), (DIAG, "bq")):
        for dr, df in dirs:
            for k in range(1, 8):
                rr, ff = r + k*dr, f + k*df
                if not inb(rr, ff): break
                c2 = cls
                if k == 1:
                    c2 += "k"
                    if dr == -1 and df != 0: c2 += "p"
                c = {s: "[KXY]", rr*8+ff: "[%s]" % c2}
                for j in range(1, k):
                    c[(r+j*dr)*8 + f+j*df] = "1"
                alts.append(seq(c))
    for dr, df in [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]:
        rr, ff = r+dr, f+df
        if inb(rr, ff):
            alts.append(seq({s: "[KXY]", rr*8+ff: "n"}))
    add("(?m)^M(?=.{%d}[KXY])(?:%s).*$" % (s, "|".join(alts)), "")
add(r"\n+", "\n"); add(r"\A\n+", ""); add(r"\n+\Z", "")

# ---- castling rights cleanup ----
for pos, ch, rm in [(60,"K","K"),(60,"K","Q"),(63,"R","K"),(56,"R","Q"),(4,"k","k"),(4,"k","q"),(7,"r","k"),(0,"r","q")]:
    add(r"(?m)^(M.{%d}[^%s].{%d} [^ ]*)%s" % (pos, ch, 63-pos, rm), r"\1")
add(r"(?m)^(M.{64})  ", r"\1 - ")

# ---- output formatting ----
add("X", "R"); add("Y", "1")
add(r"(?m)^M" + "(.{8})"*8, "/".join(r"\g<%d>" % i for i in range(1, 9)))
for d in range(8, 1, -1):
    add("1" * d, str(d))
add(r"(?m)^(\S+) (\S+) (\S+)$", r"\1 b \2 \3 0 0")

json.dump(R, open(OUT, "w"))
print(len(R))
